window.PAINTINGS = [
 { id:'starry', title:'Die Sternennacht', artist:'Vincent van Gogh', year:'1889', regions:648, colors:18,
   technique:'Öl auf Leinwand, mit dickem Farbauftrag (Impasto) und kurzen, geschwungenen Pinselstrichen.',
   story:'Van Gogh malte das Bild im Juni 1889 in der Nervenheilanstalt Saint-Paul-de-Mausole in Saint-Rémy-de-Provence, wo er sich freiwillig hatte aufnehmen lassen. Vorbild war der Blick aus seinem Fenster nach Osten, kurz vor Sonnenaufgang.',
   facts:['Gemalt hat er tagsüber und aus der Erinnerung: Das Dorf mit dem Kirchturm sah er so gar nicht von seinem Fenster aus. Es ist zum grossen Teil erfunden.',
          'Van Gogh selbst war nicht zufrieden. In einem Brief an seinen Malerfreund Émile Bernard nannte er sein Greifen nach zu grossen Sternen einen weiteren Fehlschlag. Heute ist es eines der berühmtesten Bilder der Welt.'],
   museum:'The Museum of Modern Art (MoMA), New York',
   source:'Wikimedia Commons: «Van Gogh - Starry Night - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'wave', title:'Die grosse Welle vor Kanagawa', artist:'Katsushika Hokusai', year:'um 1830–1832', regions:243, colors:15,
   technique:'Farbholzschnitt: Für jede Farbe wurde ein eigener Holzblock geschnitzt und nacheinander auf Papier gedruckt.',
   story:'Das Blatt gehört zur Serie «36 Ansichten des Berges Fuji». Hokusai war damals schon rund siebzig Jahre alt. Schau genau hin: Ganz klein, unter der Welle, steht der Fuji, und in den Booten ducken sich die Ruderer.',
   facts:['Es gibt nicht nur ein Original: Als Holzschnitt wurde das Bild in grosser Auflage gedruckt. Heute besitzen viele Museen auf der Welt einen eigenen Abzug.',
          'Das kräftige Blau ist Berliner Blau, ein künstliches Pigment aus Europa. In Japan war es damals neu und gross in Mode.'],
   museum:'The Metropolitan Museum of Art, New York (dieser Abzug)',
   source:'Wikimedia Commons: «Tsunami by hokusai 19th century.jpg», gemeinfrei (Public Domain)' },
 { id:'pearl', title:'Das Mädchen mit dem Perlenohrring', artist:'Johannes Vermeer', year:'um 1665', regions:334, colors:20,
   technique:'Öl auf Leinwand. Vermeer arbeitete mit feinen Lasuren und weichen Übergängen von Licht und Schatten.',
   story:'Das Bild ist kein klassisches Porträt, sondern eine sogenannte «Tronie»: die Studie eines Gesichts mit einem fantasievollen Kostüm, hier einem Turban. Wer das Mädchen war, weiss bis heute niemand.',
   facts:['Die Perle ist eine Illusion: Sie besteht nur aus ein paar Pinselstrichen mit heller Farbe. Untersuchungen haben gezeigt, dass sogar der Haken fehlt, an dem sie am Ohr hängen müsste.',
          'Für das Blau des Turbans nahm Vermeer Ultramarin, ein Pigment aus dem Halbedelstein Lapislazuli. Es gehörte damals zu den teuersten Farben überhaupt.'],
   museum:'Mauritshuis, Den Haag',
   source:'Wikimedia Commons: «1665 Girl with a Pearl Earring.jpg», gemeinfrei (Public Domain), Ausschnitt' },
 { id:'lilies', title:'Seerosen', artist:'Claude Monet', year:'1906', regions:586, colors:18,
   technique:'Öl auf Leinwand, mit lockeren, sichtbaren Pinselstrichen, typisch für den Impressionismus.',
   story:'Monet malte die Seerosen in seinem eigenen Garten in Giverny, nordwestlich von Paris. Den Seerosenteich hatte er selbst anlegen lassen, als Motiv für seine Bilder.',
   facts:['Auf dem Bild gibt es weder Ufer noch Horizont. Den Himmel siehst du nur als Spiegelung im Wasser.',
          'Die Seerosen liessen ihn nicht mehr los: In seinen letzten knapp dreissig Lebensjahren malte er rund 250 Seerosenbilder.'],
   museum:'The Art Institute of Chicago',
   source:'Wikimedia Commons: «Claude Monet - Water Lilies - 1906, Ryerson.jpg», gemeinfrei (Public Domain)' },
 { id:'kiss', title:'Der Kuss', artist:'Gustav Klimt', year:'1907–1908', regions:454, colors:20,
   technique:'Öl auf Leinwand mit aufgelegtem Blattgold, typisch für Klimts «Goldene Periode».',
   story:'Ein Liebespaar umarmt sich am Rand einer Blumenwiese, eingehüllt in einen goldenen Mantel. Das Bild ist quadratisch, rund 1,80 auf 1,80 Meter, und gilt als Hauptwerk des Wiener Jugendstils.',
   facts:['Schau auf die Muster: Beim Mann sind es eckige, schwarz-weisse Formen, bei der Frau runde, bunte Blumen und Kreise.',
          'Der österreichische Staat kaufte das Bild schon 1908, gleich bei seiner ersten Ausstellung in Wien.'],
   museum:'Belvedere, Wien',
   source:'Wikimedia Commons: «The Kiss - Gustav Klimt - Google Cultural Institute.jpg», gemeinfrei (Public Domain)' },
 { id:'nightwatch', title:'Die Nachtwache (Ausschnitt)', artist:'Rembrandt van Rijn', year:'1642', regions:425, colors:16,
   technique:'Öl auf Leinwand, mit starken Hell-Dunkel-Kontrasten. Rembrandt setzt Licht gezielt auf einzelne Figuren.',
   story:'Das riesige Gruppenbild zeigt eine Amsterdamer Bürgerwehr, angeführt von Hauptmann Frans Banninck Cocq in Schwarz mit roter Schärpe und seinem Leutnant in Hellgelb. Du hast den Ausschnitt mit den beiden Anführern gemalt.',
   facts:['Eigentlich spielt die Szene am Tag. Den Namen «Nachtwache» bekam das Bild erst viel später, weil der Firnis stark nachgedunkelt war.',
          '1715 wurde das Gemälde auf allen Seiten beschnitten, damit es im Amsterdamer Rathaus an die vorgesehene Wand passte.'],
   museum:'Rijksmuseum, Amsterdam',
   source:'Wikimedia Commons: «The Nightwatch by Rembrandt - Rijksmuseum.jpg», gemeinfrei (Public Domain), Ausschnitt' },
 { id:'venus', title:'Die Geburt der Venus', artist:'Sandro Botticelli', year:'um 1485', regions:526, colors:18,
   technique:'Tempera auf Leinwand. Die Farben wurden mit Ei als Bindemittel angerührt.',
   story:'Venus, die Göttin der Liebe, steht auf einer Muschel. Links blasen die Windgötter sie ans Ufer, rechts wartet eine Frau mit einem Mantel voller Blumen.',
   facts:['Im 16. Jahrhundert hing das Bild in einer Villa der Medici, der berühmten Florentiner Familie. Wer es bestellt hat, weiss man bis heute nicht sicher.',
          'Botticelli malte auf Leinwand. Damals entstanden die meisten Gemälde in Florenz noch auf Holztafeln.'],
   museum:'Uffizien, Florenz',
   source:'Wikimedia Commons: «Sandro Botticelli - La nascita di Venere - Google Art Project - edited.jpg», gemeinfrei (Public Domain)' },
 { id:'sunrise', title:'Impression, Sonnenaufgang', artist:'Claude Monet', year:'1872', regions:258, colors:14,
   technique:'Öl auf Leinwand, mit schnellen, lockeren Pinselstrichen, die nur einen Eindruck festhalten.',
   story:'Monet malte den Hafen von Le Havre, wo er aufgewachsen war, im Morgendunst: Boote, Kräne, Rauch und eine orange Sonne, die sich im Wasser spiegelt.',
   facts:['Dieses Bild gab einer ganzen Kunstrichtung den Namen. 1874 spottete ein Kritiker nach dem Titel über die «Impressionisten», und der Name blieb.',
          'Die orange Sonne ist fast gleich hell wie der graue Himmel rundherum. Darum scheint sie zu flimmern, wenn du sie ansiehst.'],
   museum:'Musée Marmottan Monet, Paris',
   source:'Wikimedia Commons: «Monet - Impression, Sunrise.jpg», gemeinfrei (Public Domain)' },
 { id:'sunflowers', title:'Sonnenblumen', artist:'Vincent van Gogh', year:'1888', regions:353, colors:18,
   technique:'Öl auf Leinwand, mit dickem Farbauftrag und vielen Gelbtönen, auch dem damals neuen Chromgelb.',
   story:'Van Gogh malte die Sonnenblumen in Arles in Südfrankreich. Er wollte damit das Zimmer für seinen Malerfreund Paul Gauguin schmücken, der ihn besuchen kam.',
   facts:['Von den Sonnenblumen in der Vase gibt es mehrere Fassungen. Sie hängen heute unter anderem in London, Amsterdam, München, Philadelphia und Tokio.',
          'Van Gogh signierte das Bild nicht unten in der Ecke, sondern mitten auf der Vase: «Vincent».'],
   museum:'The National Gallery, London',
   source:'Wikimedia Commons: «Vincent van Gogh - Sunflowers (1888, National Gallery London).jpg», gemeinfrei (Public Domain)' },
 { id:'cafe', title:'Caféterrasse am Abend', artist:'Vincent van Gogh', year:'1888', regions:396, colors:18,
   technique:'Öl auf Leinwand. Leuchtendes Gelb und Orange stehen gegen ein tiefes Blau.',
   story:'Das Bild zeigt ein Strassencafé an der Place du Forum in Arles. Van Gogh malte direkt vor Ort, unter dem Gaslicht der Terrasse.',
   facts:['Es ist das erste Bild, in dem van Gogh einen Sternenhimmel malte, ein Jahr vor der Sternennacht.',
          'Seiner Schwester schrieb er stolz von einem Nachtbild ganz ohne Schwarz, nur mit Blau, Violett und Grün.'],
   museum:'Kröller-Müller Museum, Otterlo (Niederlande)',
   source:'Wikimedia Commons: «Vincent Willem van Gogh - Cafe Terrace at Night (Yorck).jpg», gemeinfrei (Public Domain)' },
 { id:'jatte', title:'Ein Sonntagnachmittag auf der Insel La Grande Jatte', artist:'Georges Seurat', year:'1884–1886', regions:418, colors:20,
   technique:'Pointillismus: unzählige kleine Farbpunkte nebeneinander, die sich erst in deinem Auge zu Farben mischen.',
   story:'Pariser erholen sich an einem Sonntag auf einer Insel in der Seine. Seurat arbeitete rund zwei Jahre an dem grossen Bild, das etwa zwei auf drei Meter misst.',
   facts:['Schau ganz rechts: Die elegante Dame führt einen kleinen Affen an der Leine.',
          'Später malte Seurat dem Bild noch einen Rand aus farbigen Punkten, sozusagen einen gemalten Rahmen.'],
   museum:'The Art Institute of Chicago',
   source:'Wikimedia Commons: «Georges Seurat - A Sunday on La Grande Jatte -- 1884 - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'galette', title:'Tanz im Moulin de la Galette', artist:'Pierre-Auguste Renoir', year:'1876', regions:508, colors:20,
   technique:'Öl auf Leinwand. Mit hellen Farbtupfern malt Renoir das Sonnenlicht, das durch die Blätter fällt.',
   story:'An einem Sonntagnachmittag tanzen und plaudern die Leute im Garten eines Tanzlokals auf dem Montmartre in Paris.',
   facts:['Viele der Gäste auf dem Bild sind Freunde von Renoir, zum Beispiel Maler und Schriftsteller.',
          'Seinen Namen hat das Lokal von der «Galette», einem flachen Gebäck, das man dort ass.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Auguste Renoir - Dance at Le Moulin de la Galette - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'wanderer', title:'Der Wanderer über dem Nebelmeer', artist:'Caspar David Friedrich', year:'um 1817', regions:251, colors:16,
   technique:'Öl auf Leinwand, mit fein abgestuften Grau- und Blautönen für Nebel und Ferne.',
   story:'Ein Mann steht auf einem Felsen und blickt über ein Meer aus Nebel. Das Bild ist eines der bekanntesten Werke der deutschen Romantik.',
   facts:['Den Wanderer sehen wir nur von hinten. Diese «Rückenfigur» ist typisch für Friedrich: So schauen wir mit ihm in die Landschaft.',
          'Die Felsen und Berge hat Friedrich aus Skizzen aus dem Elbsandsteingebirge zusammengesetzt, das auch Sächsische Schweiz heisst.'],
   museum:'Hamburger Kunsthalle',
   source:'Wikimedia Commons: «Caspar David Friedrich - Wanderer above the sea of fog.jpg», gemeinfrei (Public Domain)' },
 { id:'babel', title:'Der Turmbau zu Babel', artist:'Pieter Bruegel der Ältere', year:'1563', regions:536, colors:18,
   technique:'Öl auf Eichenholz, mit winzigen, genau gemalten Details.',
   story:'Nach der Bibel wollten die Menschen einen Turm bis in den Himmel bauen. Bruegel zeigt die riesige Baustelle mit Kränen, Gerüsten, Arbeitern und einer ganzen Stadt darum herum.',
   facts:['Als Vorbild für die vielen Bögen diente ihm vermutlich das Kolosseum, das er auf seiner Reise nach Rom gesehen hatte.',
          'Bruegel malte noch eine zweite, kleinere Fassung des Turms. Sie hängt heute in Rotterdam.'],
   museum:'Kunsthistorisches Museum, Wien',
   source:'Wikimedia Commons: «Pieter Bruegel the Elder - The Tower of Babel (Vienna) - Google Art Project - edited.jpg», gemeinfrei (Public Domain)' },
 { id:'redfuji', title:'Roter Fuji (Feiner Wind, klarer Morgen)', artist:'Katsushika Hokusai', year:'um 1830–1832', regions:140, colors:12,
   technique:'Farbholzschnitt, mit wenigen Farben in grossen, klaren Flächen.',
   story:'Der Fuji leuchtet rot im Morgenlicht, wie man es an manchen Tagen im Spätsommer und Herbst sehen kann. Darüber ziehen kleine Wolken.',
   facts:['Das Blatt gehört zur gleichen Serie wie «Die grosse Welle»: den «36 Ansichten des Berges Fuji».',
          'Die Serie war so beliebt, dass Hokusai später noch zehn weitere Blätter dazu schuf, also 46 statt 36.'],
   museum:'Indianapolis Museum of Art at Newfields (dieser Abzug)',
   source:'Wikimedia Commons: «Katsushika Hokusai - Fine Wind, Clear Morning (Gaifū kaisei) - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'anker', title:'Zwei schlafende Mädchen auf der Ofenbank', artist:'Albert Anker', year:'1895', regions:250, colors:18,
   technique:'Öl auf Leinwand, mit warmen Farben und ruhigem, genauem Licht.',
   story:'Zwei Mädchen sind auf der warmen Ofenbank eingeschlafen. Albert Anker malte am liebsten Kinder und den Alltag in seinem Dorf Ins im Berner Seeland.',
   facts:['Anker studierte zuerst Theologie und wollte Pfarrer werden, bevor er sich für die Malerei entschied.',
          'Er bemalte auch Hunderte von Fayence-Tellern und -Platten für eine Keramikwerkstatt in Paris.'],
   museum:'Kunsthaus Zürich',
   source:'Wikimedia Commons: «Albert Anker - Zwei schlafende Mädchen auf der Ofenbank (1895).jpg», gemeinfrei (Public Domain)' },
 { id:'hodler', title:'Thunersee mit Stockhornkette', artist:'Ferdinand Hodler', year:'1910', regions:152, colors:14,
   technique:'Öl auf Leinwand. Klare Linien und Flächen, die Berge spiegeln sich fast symmetrisch im See.',
   story:'Hodler malte den Thunersee mit dem Stockhorn immer wieder, zu verschiedenen Tageszeiten und Jahreszeiten. Er gehört zu den wichtigsten Schweizer Malern.',
   facts:['Hodler liebte Wiederholung und Symmetrie. Er nannte dieses Prinzip «Parallelismus».',
          'Hodler wurde 1853 in Bern geboren und arbeitete später vor allem in Genf.'],
   museum:'Kunsthalle Mannheim',
   source:'Wikimedia Commons: «Hodler - Thunersee mit Stockhornkette -1910.jpg», gemeinfrei (Public Domain), Ausschnitt' },
 { id:'segantini', title:'Mittag in den Alpen', artist:'Giovanni Segantini', year:'1891', regions:410, colors:16,
   technique:'Divisionismus: reine Farben in feinen Strichen nebeneinander, damit das Bergsonnenlicht besonders hell leuchtet.',
   story:'Eine Hirtin schützt ihre Augen vor der Mittagssonne, um sie herum Schafe und Bergwiesen. Segantini malte das Bild in Savognin in Graubünden, wo er damals lebte.',
   facts:['Segantini malte am liebsten draussen in den Bergen, auch bei Kälte und Wind.',
          'Er starb 1899 auf dem Schafberg oberhalb von Pontresina, wo er an seinem grossen Alpen-Triptychon arbeitete.'],
   museum:'Segantini Museum, St. Moritz',
   source:'Wikimedia Commons: «Segantini - Midday in the Alps, 1891.jpg», gemeinfrei (Public Domain)' },
 { id:'degas', title:'Die Tanzklasse', artist:'Edgar Degas', year:'1873–1876', regions:537, colors:18,
   technique:'Öl auf Leinwand. Ungewöhnliche Blickwinkel und angeschnittene Figuren wirken wie ein Schnappschuss.',
   story:'Junge Tänzerinnen warten auf ihren Einsatz, während der Ballettmeister mit seinem Stock den Takt angibt.',
   facts:['Der Ballettmeister ist Jules Perrot, früher selbst ein berühmter Tänzer.',
          'Degas malte die Szene nicht live, sondern setzte sie im Atelier aus vielen Skizzen und Posen zusammen.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Edgar Degas - The Ballet Class - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'turner', title:'Die letzte Fahrt der Temeraire', artist:'William Turner', year:'1839', regions:171, colors:18,
   technique:'Öl auf Leinwand, mit leuchtenden, fast verschwimmenden Farben für Licht und Himmel.',
   story:'Ein kleiner Dampfschlepper zieht das alte Kriegsschiff Temeraire bei Sonnenuntergang zum Abwracken. Das Segelschiff hatte 1805 in der Seeschlacht von Trafalgar gekämpft.',
   facts:['Turner nannte das Bild seinen Liebling und verkaufte es nie. Er vermachte es dem britischen Staat.',
          'Auf der heutigen 20-Pfund-Note siehst du Turner und im Hintergrund die Temeraire.'],
   museum:'The National Gallery, London',
   source:'Wikimedia Commons: «The Fighting Temeraire, JMW Turner, National Gallery.jpg», gemeinfrei (Public Domain)' },
 { id:'mondrian', title:'Komposition mit Rot, Blau und Gelb', artist:'Piet Mondrian', year:'1930', regions:9, colors:6, fresh:true,
   technique:'Öl auf Leinwand. Nur waagrechte und senkrechte Linien, dazu die Primärfarben Rot, Blau und Gelb sowie Schwarz und Weiss.',
   story:'Mondrian reduzierte die Malerei auf das Wesentliche: ein grosses rotes Rechteck, dazu ein blaues und ein gelbes Feld, gehalten von einem schwarzen Gitter. Das Bild entstand 1930 in Paris, auf Wunsch des Zürcher Architekten Alfred Roth.',
   facts:['Mondrian nannte diesen Stil «Neoplastizismus». Er wollte damit eine klare, allgemeine Harmonie zeigen, nicht eine Landschaft oder eine Person.',
          'Heute hängt das Bild im Kunsthaus Zürich. Roth schenkte es dem Museum 1987.'],
   museum:'Kunsthaus Zürich',
   source:'Wikimedia Commons: «Piet Mondriaan, 1930 - Mondrian Composition II in Red, Blue, and Yellow.jpg», gemeinfrei (Public Domain)' },
 { id:'whistler', title:'Arrangement in Grau und Schwarz Nr. 1', artist:'James McNeill Whistler', year:'1871', regions:59, colors:10, fresh:true,
   technique:'Öl auf Leinwand, mit zurückhaltenden Grau-, Schwarz- und Silbertönen.',
   story:'Whistler malte seine Mutter Anna im Profil, sitzend in einem grauen Raum. Er nannte das Bild bewusst ein «Arrangement»: Ihm ging es um Flächen, Linien und Töne, nicht um ein typisches Porträt.',
   facts:['Schnell bekam das Bild den Beinamen «Whistlers Mutter» und wurde zu einem der bekanntesten amerikanischen Gemälde.',
          'Whistler war Amerikaner, lebte aber lange in London und Paris. Das Bild hängt heute im Musée d’Orsay.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «James Abbott McNeill Whistler - Portrait of the Artist\'s Mother - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'angelus', title:'Das Angelusläuten', artist:'Jean-François Millet', year:'1857–1859', regions:89, colors:12, fresh:true,
   technique:'Öl auf Leinwand, mit erdigen Farben und einem weichen, abendlichen Licht.',
   story:'Zwei Bauern auf dem Feld legen die Arbeit nieder und beten. Im Hintergrund liegt eine Kirche: Von dort läutet das Angelus, das Gebet am Morgen, mittags und am Abend.',
   facts:['Millet selbst war als Bauernsohn aufgewachsen. Er malte das Landleben ohne Pathos, aber mit grossem Ernst.',
          'Im 19. Jahrhundert wurde das Bild enorm beliebt. Reproduktionen hingen in unzähligen Wohnungen.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Jean-François Millet - The Angelus - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'gypsy', title:'Die schlafende Bohémienne', artist:'Henri Rousseau', year:'1897', regions:107, colors:12, fresh:true,
   technique:'Öl auf Leinwand, in der klaren, flächigen Art der naiven Malerei.',
   story:'Eine Frau schläft in der Wüste, neben sich eine Mandoline und einen Wasserkrug. Ein Löwe tritt an sie heran und beschnuppert sie, unter einem vollen Mond.',
   facts:['Rousseau war ein Selbstlerner und hatte nie eine Kunstakademie besucht. Die Wüste und den Löwen hat er nicht selbst gesehen, sondern sich ausgedacht.',
          'Zu Lebzeiten wurde er oft belächelt. Heute hängt das Bild im Museum of Modern Art in New York.'],
   museum:'The Museum of Modern Art (MoMA), New York',
   source:'Wikimedia Commons: «Henri Rousseau - La Bohémienne endormie - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'senecio', title:'Senecio', artist:'Paul Klee', year:'1922', regions:135, colors:12, fresh:true,
   technique:'Öl auf Mull, auf Karton aufgezogen. Das Gesicht ist aus einfachen, geometrischen Flächen gebaut.',
   story:'Ein Gesicht aus Kreisen, Vierecken und warmen Farben, fast wie eine Maske oder eine Kinderzeichnung. Den Titel «Senecio» (lat. «Greis») nahm Klee von einer Pflanzengattung, dem Greiskraut.',
   facts:['Klee wurde 1879 in Münchenbuchsee bei Bern geboren. Er unterrichtete am Bauhaus und gilt als einer der wichtigsten Künstler der Moderne.',
          'Das Bild hängt im Kunstmuseum Basel, unweit von Klees Schweizer Heimat.'],
   museum:'Kunstmuseum Basel',
   source:'Wikimedia Commons: «Paul Klee, 1922, Senecio, oil on gauze, 40.3 × 37.4 cm, Kunstmuseum Basel.jpg», gemeinfrei (Public Domain)' },
 { id:'milkmaid', title:'Die Milchmagd', artist:'Johannes Vermeer', year:'um 1658–1660', regions:164, colors:16, fresh:true,
   technique:'Öl auf Leinwand. Vermeer setzt kleine Lichtpunkte auf Brot, Krug und Stoff, damit die Dinge zu leuchten scheinen.',
   story:'Eine Küchenmagd giesst Milch aus einem Krug. Daneben liegen Brot und ein Korb. Es ist ein stiller, konzentrierter Augenblick bei der Arbeit.',
   facts:['Unten an der Wand siehst du Delfter Fliesen mit kleinen Figuren, typisch für holländische Küchen der Zeit.',
          'Das leuchtende Blau der Schürze besteht unter anderem aus Ultramarin, das aus Lapislazuli gewonnen und teuer gehandelt wurde.'],
   museum:'Rijksmuseum, Amsterdam',
   source:'Wikimedia Commons: «Johannes Vermeer - Het melkmeisje - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'ballon', title:'Der Ball', artist:'Félix Vallotton', year:'1899', regions:168, colors:12, fresh:true,
   technique:'Öl auf Karton, mit klaren, fast flachen Farbfeldern und scharfen Schatten, beeinflusst von japanischen Holzschnitten.',
   story:'Von oben sieht man ein Kind in einem Park einer roten Kugel nachlaufen. Zwei kleine Figuren stehen im Schatten der Bäume. Vallotton, geboren in Lausanne, malte die Szene wahrscheinlich in den Tuilerien in Paris.',
   facts:['Vallotton gehörte in Paris zur Künstlergruppe der Nabis. Bekannt wurde er auch durch seine schwarz-weissen Holzschnitte.',
          'Das Bild hängt heute im Musée d’Orsay. Vallotton blieb seiner Schweizer Herkunft verbunden und kehrte oft in die Heimat zurück.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Félix Vallotton - The Ball - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'monalisa', title:'Mona Lisa', artist:'Leonardo da Vinci', year:'um 1503–1506', regions:188, colors:16, fresh:true,
   technique:'Öl auf Pappelholz, mit sehr weichen Übergängen (Sfumato), besonders um Mund und Augen.',
   story:'Eine Frau sitzt vor einer weiten, etwas geheimnisvollen Landschaft und blickt uns an. Ihr leichtes Lächeln hat das Bild weltberühmt gemacht. Wahrscheinlich zeigt es Lisa del Giocondo, die Frau eines florentinischen Kaufmanns.',
   facts:['Leonardo nahm das Bild mit nach Frankreich, als er an den Hof von König Franz I. ging. Deshalb hängt es heute im Louvre und nicht in Italien.',
          'Die Tafel ist kleiner, als viele denken: nur etwa 77 auf 53 Zentimeter.'],
   museum:'Musée du Louvre, Paris',
   source:'Wikimedia Commons: «Mona Lisa, by Leonardo da Vinci, from C2RMF retouched.jpg», gemeinfrei (Public Domain)' },
 { id:'ruegen', title:'Kreidefelsen auf Rügen', artist:'Caspar David Friedrich', year:'um 1818', regions:201, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Die weissen Klippen, das Meer und die drei Figuren sind sorgfältig gegeneinander gesetzt.',
   story:'Durch ein Fenster aus Bäumen und Kreidefelsen blickt man aufs Meer. Unten sitzen drei Menschen: wahrscheinlich Friedrich selbst, seine Frau Caroline und sein Bruder. Das Bild entstand nach der Hochzeitsreise auf die Insel Rügen.',
   facts:['Die Frau im roten Kleid zeigt auf etwas im Abgrund, der Mann in der Mitte beugt sich weit hinunter, der dritte schaut in die Ferne.',
          'Das Gemälde gehört zur Sammlung Oskar Reinhart in Winterthur.'],
   museum:'Museum Oskar Reinhart, Winterthur',
   source:'Wikimedia Commons: «Caspar David Friedrich - Kreidefelsen auf Rügen (1818).jpg», gemeinfrei (Public Domain)' },
 { id:'gothic', title:'American Gothic', artist:'Grant Wood', year:'1930', regions:204, colors:16, fresh:true,
   technique:'Öl auf Faserplatte, mit glatten, klaren Formen und vielen feinen Details.',
   story:'Ein Bauer mit Heugabel und eine Frau stehen vor einem Holzhaus mit spitzem «gotischem» Fenster. Wood malte das Bild in Iowa, nach einem Haus, das er in der kleinen Stadt Eldon gesehen hatte.',
   facts:['Als Modelle dienten Woods Schwester Nan und sein Zahnarzt. Sie sollten nicht ein bestimmtes Ehepaar darstellen, sondern einen Typus.',
          'Der Titel bezieht sich auf das Fenster im Stil der «Carpenter Gothic», einer amerikanischen Holz-Gotik.'],
   museum:'The Art Institute of Chicago',
   source:'Wikimedia Commons: «Grant Wood - American Gothic - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'macke', title:'Dame in grüner Jacke', artist:'August Macke', year:'1913', regions:258, colors:16, fresh:true,
   technique:'Öl auf Leinwand, mit leuchtenden, flächigen Farben, typisch für den Rheinischen Expressionismus.',
   story:'Spaziergänger stehen in einem Park, im Hintergrund das Blau eines Sees. Macke malte das Bild 1913 in Hilterfingen am Thunersee, wo er mehrere Monate mit seiner Frau Elisabeth verbrachte.',
   facts:['Macke war ein enger Freund von Franz Marc und gehörte zum Kreis des Blauen Reiters.',
          'Nur ein Jahr später, im September 1914, fiel er im Ersten Weltkrieg. Er wurde nur 27 Jahre alt.'],
   museum:'Museum Ludwig, Köln',
   source:'Wikimedia Commons: «Dame in grüner Jacke - August Macke - Museum Ludwig-7004 (cropped).jpg», gemeinfrei (Public Domain)' },
 { id:'arearea', title:'Arearea (Fröhlichkeit)', artist:'Paul Gauguin', year:'1892', regions:261, colors:16, fresh:true,
   technique:'Öl auf Leinwand, mit kräftigen, flächigen Farben und klaren Umrissen, fern vom europäischen Impressionismus.',
   story:'Zwei tahitianische Frauen sitzen auf einer Wiese, davor ein roter Hund. Im Hintergrund spielt jemand auf einer Flöte vor einer Götterfigur. «Arearea» bedeutet auf Tahitianisch so viel wie Freude oder Vergnügen.',
   facts:['Gauguin reiste 1891 nach Tahiti, auf der Suche nach einem Leben abseits der modernen europäischen Welt.',
          'Viele Motive holte er sich aus dem Alltag, aus Schnitzereien und aus seiner eigenen Fantasie. Das Bild hängt im Musée d’Orsay.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Paul Gauguin - Arearea - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'bath', title:'Das Kinderbad', artist:'Mary Cassatt', year:'1893', regions:271, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Der Blick von oben und die flachen Muster sind von japanischen Farbholzschnitten inspiriert.',
   story:'Eine Mutter wäscht dem Kind die Füsse in einer Schüssel. Cassatt, eine Amerikanerin in Paris, malte besonders oft den stillen Alltag von Frauen und Kindern.',
   facts:['Cassatt war mit den Impressionisten befreundet, vor allem mit Edgar Degas, und stellte mit ihnen aus.',
          'Sie blieb ihr Leben lang unverheiratet und unterstützte später Museen in den USA beim Kauf moderner französischer Kunst.'],
   museum:'The Art Institute of Chicago',
   source:'Wikimedia Commons: «Mary Cassatt - The Child\'s Bath - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'arnolfini', title:'Arnolfini-Porträt', artist:'Jan van Eyck', year:'1434', regions:301, colors:20, fresh:true,
   technique:'Öl auf Eichenholz, mit winzigen, fast mikroskopisch genauen Details.',
   story:'Ein Paar steht in einem Wohnraum in Brügge, wahrscheinlich der italienische Kaufmann Giovanni di Nicolao Arnolfini und seine Frau. Er hebt die Hand, sie legt die ihre in die seine.',
   facts:['Im konvexen Spiegel an der Wand siehst du den Raum noch einmal, und darin zwei weitere Gestalten an der Tür.',
          'Über dem Spiegel steht in lateinischer Schrift: «Johannes de eyck fuit hic 1434» – Jan van Eyck war hier, 1434.'],
   museum:'The National Gallery, London',
   source:'Wikimedia Commons: «Van Eyck - Arnolfini Portrait.jpg», gemeinfrei (Public Domain)' },
 { id:'haywain', title:'Der Heuwagen', artist:'John Constable', year:'1821', regions:342, colors:18, fresh:true,
   technique:'Öl auf Leinwand, mit lebhaftem Himmel und vielen Grüntönen der englischen Landschaft.',
   story:'Ein Heuwagen fährt durch den Fluss Stour bei Flatford in Suffolk, ganz in der Nähe der Mühle von Constables Vater. Links steht ein Haus, das es heute noch gibt.',
   facts:['Constable malte am liebsten die Landschaft seiner Kindheit. Grosse Anerkennung fand er zuerst in Frankreich, erst später in England.',
          'Das Haus links gehört zu einem Bauernhof und heisst Willy Lotts Cottage. Es steht noch immer am selben Ort.'],
   museum:'The National Gallery, London',
   source:'Wikimedia Commons: «John Constable - The Hay Wain (1821).jpg», gemeinfrei (Public Domain)' },
 { id:'cards', title:'Die Kartenspieler', artist:'Paul Cézanne', year:'um 1894–1895', regions:365, colors:16, fresh:true,
   technique:'Öl auf Leinwand. Die Figuren und der Tisch sind aus ruhigen, festen Farbflächen gebaut.',
   story:'Zwei Männer sitzen an einem kleinen Tisch und spielen Karten, ohne dass einer den anderen ansieht. Cézanne malte mehrere Fassungen dieses Motivs. Diese hier mit zwei Spielern gehört zu den bekanntesten.',
   facts:['Als Modelle dienten ihm Bauern vom Gut seiner Familie in der Provence.',
          'Von den Kartenspielern gibt es fünf Fassungen. Diese hängt im Musée d’Orsay in Paris.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Paul Cézanne - Les Joueurs de cartes.jpg», gemeinfrei (Public Domain)' },
 { id:'poppies', title:'Mohnfeld bei Argenteuil', artist:'Claude Monet', year:'1873', regions:365, colors:18, fresh:true,
   technique:'Öl auf Leinwand, mit lockeren Pinselstrichen für das Gras, den Mohn und die Wolken.',
   story:'Über eine Sommerwiese bei Argenteuil, wo Monet damals lebte, gehen eine Frau und ein Kind, wahrscheinlich seine Frau Camille und der Sohn Jean. Links leuchtet der Mohn besonders dicht.',
   facts:['Das Bild war 1874 auf der ersten Ausstellung der Impressionisten in Paris zu sehen.',
          'Monet malte später noch weitere Mohnfelder, unter anderem in Vétheuil und in Giverny.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Claude Monet - Poppy Field - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'scream', title:'Der Schrei', artist:'Edvard Munch', year:'1893', regions:421, colors:16, fresh:true,
   technique:'Öl, Tempera und Pastell auf Karton, mit wellenförmigen Linien in Himmel, Wasser und Figur.',
   story:'Eine Figur steht auf einer Brücke, hält sich die Ohren zu und öffnet den Mund. Der Himmel ist blutrot. Munch schrieb, er habe bei einem Spaziergang bei Sonnenuntergang einen Schrei durch die Natur gehört.',
   facts:['Von diesem Motiv gibt es mehrere Fassungen. Dies ist die berühmte von 1893, heute im Nationalmuseum in Oslo.',
          'Im Hintergrund gehen zwei dunkle Gestalten ruhig weiter, als merkten sie nichts von der inneren Erschütterung.'],
   museum:'Nasjonalmuseet, Oslo',
   source:'Wikimedia Commons: «Edvard Munch - The Scream - NG.M.00939 - National Museum of Art, Architecture and Design.jpg», gemeinfrei (Public Domain)' },
 { id:'liberty', title:'Die Freiheit führt das Volk', artist:'Eugène Delacroix', year:'1830', regions:443, colors:18, fresh:true,
   technique:'Öl auf Leinwand, mit dramatischem Licht und einer komponierten, bewegten Menge.',
   story:'Eine Frau mit der französischen Trikolore schreitet barfuss über eine Barrikade, den Kopf mit der phrygischen Mütze bedeckt. Um sie herum kämpfen Bürger, Arbeiter und ein Junge mit Pistolen. Das Bild erinnert an die Julirevolution von 1830 in Paris.',
   facts:['Die Frau ist keine bestimmte Person, sondern eine Allegorie der Freiheit.',
          'Der Junge mit den Pistolen gilt als eine Anregung für die Figur des Gavroche in Victor Hugos Roman «Die Elenden».'],
   museum:'Musée du Louvre, Paris',
   source:'Wikimedia Commons: «La Liberté guidant le peuple - Eugène Delacroix - Musée du Louvre Peintures RF 129 - après restauration 2024.jpg», gemeinfrei (Public Domain)' },
 { id:'folies', title:'Eine Bar in den Folies-Bergère', artist:'Édouard Manet', year:'1882', regions:443, colors:18, fresh:true,
   technique:'Öl auf Leinwand. Im Spiegel hinter der Theke erscheint der ganze Saal noch einmal.',
   story:'Eine Kellnerin steht an der Bar des Pariser Varietés Folies-Bergère, vor sich Flaschen, Obst und ein Glas. Hinter ihr zeigt der Spiegel das Publikum, die Lichter – und einen Mann, mit dem sie offenbar spricht.',
   facts:['Schau genau auf den Spiegel: Die Spiegelung der Frau und des Mannes stimmt nicht ganz mit unserem Blickwinkel überein. Das rätselt die Forschung bis heute.',
          'Es ist eines der letzten grossen Bilder Manets. Er starb im Jahr darauf, 1883.'],
   museum:'The Courtauld Gallery, London',
   source:'Wikimedia Commons: «"Un Bar aux Folies-Bergère" by Édouard Manet (1882).jpg», gemeinfrei (Public Domain)' },
 { id:'thunder', title:'Gewitter unterhalb des Gipfels', artist:'Katsushika Hokusai', year:'um 1830–1832', regions:41, colors:10, fresh:true,
   technique:'Farbholzschnitt aus der Serie «36 Ansichten des Berges Fuji».',
   story:'Hokusai zeigt den Fuji bei einem Sommergewitter: Der Gipfel bleibt still im Licht, während unten rote Blitze über den Hang zucken. Das Blatt heisst auf Japanisch «Sanka hakuu» – ein Gewitter unterhalb des Gipfels.',
   facts:['Die Serie erschien, als Hokusai schon über siebzig war. Der Fuji kommt darin bei Wind, bei Sonne und eben auch bei Sturm vor.',
          'Das Blatt gehört zur gleichen Folge wie die grosse Welle und der rote Fuji, die schon in der Galerie sind.'],
   museum:'Centre Céramique, Maastricht (dieser Abzug)',
   source:'Wikimedia Commons: «Katsushika Hokusai (1760-1849), Donderbui onder de top (1829-33).jpg», gemeinfrei (Public Domain)' },
 { id:'fifre', title:'Der Pfeifer', artist:'Édouard Manet', year:'1866', regions:55, colors:10, fresh:true,
   technique:'Öl auf Leinwand. Manet setzt grosse, klare Farbflächen und einen fast leeren, hellen Grund.',
   story:'Ein junger Musiker der kaiserlichen Garde steht wie auf einer Bühne vor einem neutralen Hintergrund. Manet malte ihn 1866, ohne viel Drumherum: Die Figur allein soll wirken, fast wie auf einem Spielkartenbild.',
   facts:['Als das Bild ausgestellt wurde, fanden es viele zu flach und zu kühn. Genau diese Schlichtheit macht es heute so modern.',
          'Das kräftige Rot der Hose und das schwarze Jacket sind bewusst gegeneinander gesetzt. So tritt der Junge deutlich hervor.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Manet, Edouard - Young Flautist, or The Fifer, 1866 (2).jpg», gemeinfrei (Public Domain)' },
 { id:'remself', title:'Selbstbildnis', artist:'Rembrandt van Rijn', year:'1659', regions:110, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Rembrandt modelliert das Gesicht mit warmem Licht und tiefem Dunkel.',
   story:'Rembrandt war 53, als er dieses Bild malte. Er hatte Schulden, hatte sein schönes Haus verloren – und schaut uns trotzdem ruhig an, in einem dunklen Mantel und mit einer Samtkappe.',
   facts:['Rembrandt hat sich über vierzigmal selbst gemalt, von der Jugend bis ins Alter. So können wir sein Gesicht durch das ganze Leben verfolgen.',
          'Das Licht sitzt vor allem auf Stirn, Nase und Wangen. Alles andere tritt zurück, damit der Blick bleibt.'],
   museum:'National Gallery of Art, Washington',
   source:'Wikimedia Commons: «Rembrandt van Rijn - Self-Portrait - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'wing', title:'Flügel einer Blauracke', artist:'Albrecht Dürer', year:'um 1512', regions:113, colors:10, fresh:true,
   technique:'Aquarell und Deckfarben auf Pergament, mit feinen Federlinien.',
   story:'Dürer hat den Flügel eines bunten Vogels so genau gemalt, als läge er noch vor uns auf dem Tisch. Jede Feder ist einzeln gesetzt, von den kräftigen Schwingen bis zu den weichen, hellen Deckfedern.',
   facts:['Die Blauracke ist ein südlicher Vogel mit Türkis, Blau und warmem Braun im Gefieder. Dürer hielt ihn wie ein Forscher fest.',
          'Das Blatt gehört zu seinen berühmten Naturstudien, zusammen mit dem Feldhasen und dem Stück Rasen.'],
   museum:'Albertina, Wien',
   source:'Wikimedia Commons: «Duerer wing of a blue roller.jpg», gemeinfrei (Public Domain)' },
 { id:'ohashi', title:'Plötzlicher Regen über der Shin-Ohashi-Brücke', artist:'Utagawa Hiroshige', year:'1857', regions:115, colors:12, fresh:true,
   technique:'Farbholzschnitt aus der Serie «Hundert berühmte Ansichten von Edo».',
   story:'Mitten in Edo, dem heutigen Tokio, überrascht ein Sommerregen die Menschen auf der Brücke. Die Schirme neigen sich, die Planken glänzen, und der Fluss liegt dunkel darunter.',
   facts:['Hiroshige war ein Meister des Wetters. Regen, Schnee und Mondschein kommen in seinen Blättern immer wieder vor.',
          'Das Motiv hat später auch westliche Maler beeindruckt. Vincent van Gogh kopierte dieses Blatt in Öl.'],
   museum:'Library of Congress, Washington (dieser Abzug)',
   source:'Wikimedia Commons: «Hiroshige, Sudden shower over Shin-Ōhashi bridge and Atake, 1857.jpg», gemeinfrei (Public Domain)' },
 { id:'gravelines', title:'Der Kanal von Gravelines am Abend', artist:'Georges Seurat', year:'1890', regions:139, colors:12, fresh:true,
   technique:'Öl auf Leinwand, in kleinen, nebeneinander gesetzten Farbpunkten (Pointillismus).',
   story:'Seurat verbrachte den Sommer 1890 in dem kleinen Hafen Gravelines an der Nordsee. Am Abend wird das Wasser hell, der Himmel rosa, und ganz vorn lehnt ein grosser Anker am Kai.',
   facts:['Die dunkle Umrandung hat Seurat selbst gemalt. Sie gehört zum Bild, wie ein Rahmen aus Farbe.',
          'Ein Jahr später starb er, erst 31 Jahre alt. Die Hafenbilder von Gravelines gehören zu seinem letzten Sommer.'],
   museum:'The Museum of Modern Art (MoMA), New York',
   source:'Wikimedia Commons: «Georges-Pierre Seurat - The Channel at Gravelines, Evening - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'ermine', title:'Dame mit dem Hermelin', artist:'Leonardo da Vinci', year:'um 1489–1491', regions:140, colors:14, fresh:true,
   technique:'Öl auf Holztafel. Leonardo modelliert Gesicht und Tier mit sehr weichen Übergängen (Sfumato).',
   story:'Das junge Mädchen ist Cecilia Gallerani, eine gebildete Dame am Hof von Mailand. Der Hermelin auf ihrem Arm war ein Symbol für Reinheit – und ein Wortspiel auf ihren Namen.',
   facts:['Leonardo arbeitete damals für den Herzog Ludovico Sforza in Mailand. Cecilia war eine der klügsten Frauen an diesem Hof.',
          'Das Bild gehört zu den wenigen allgemein anerkannten Gemälden Leonardos und ist ein Stolz von Krakau.'],
   museum:'Muzeum Książąt Czartoryskich, Krakau',
   source:'Wikimedia Commons: «Lady with an Ermine - Leonardo da Vinci - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'avemaria', title:'Ave Maria bei der Überfahrt', artist:'Giovanni Segantini', year:'1886', regions:147, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Segantini setzte die Farbe in feinen, nebeneinander liegenden Strichen.',
   story:'Ein Hirt und eine Frau gleiten im Kahn über einen stillen Bergsee, das Schaf im Bug, der Himmel schon abendlich. In diesem Augenblick falten sie die Hände zum Ave Maria.',
   facts:['Segantini malte das Motiv zweimal. Diese zweite Fassung von 1886 brachte ihm in Paris eine Goldmedaille ein.',
          'Er lebte hoch oben im Engadin und malte das bäuerliche Leben in den Alpen mit grosser Ruhe und Genauigkeit.'],
   museum:'Segantini Museum, St. Moritz',
   source:'Wikimedia Commons: «Segantini - Ave Maria Crossing the Lake, 1886.jpg», gemeinfrei (Public Domain)' },
 { id:'naeherin', title:'Die kleine Näherin', artist:'Albert Anker', year:'1908', regions:152, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Anker beobachtet Alltagsszenen aus dem Berner Seeland sehr genau und liebevoll.',
   story:'Ein Mädchen sitzt über ihre Näharbeit gebeugt, das blonde Haar sorgfältig geflochten. Anker malt keine grosse Heldin, sondern ein Kind bei der stillen Arbeit – typisch für ihn.',
   facts:['Albert Anker stammt aus Ins am Murtensee. Viele seiner Bilder zeigen Kinder beim Lernen, Spielen oder Helfen.',
          'Das Bild entstand 1908, zwei Jahre vor seinem Tod. Die Ruhe der Szene ist typisch für sein Spätwerk.'],
   museum:'Privatbesitz',
   source:'Wikimedia Commons: «Albert Anker - Die kleine Näherin.jpg», gemeinfrei (Public Domain)' },
 { id:'cradle', title:'Die Wiege', artist:'Berthe Morisot', year:'1872', regions:171, colors:10, fresh:true,
   technique:'Öl auf Leinwand. Morisot arbeitet mit hellen Tönen und lockeren, sichtbaren Pinselstrichen.',
   story:'Edma, die Schwester der Malerin, wacht über ihre schlafende Tochter Blanche. Der weisse Schleier der Wiege teilt das Bild sanft in zwei Hälften: die Mutter und das Kind.',
   facts:['Berthe Morisot war eine der wenigen Frauen im engen Kreis der Impressionisten und stellte mit ihnen zusammen aus.',
          'Das Bild ist zärtlich, aber nicht süsslich. Man spürt die Stille eines Zimmers am Nachmittag.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Berthe Morisot - The Cradle - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'gleaners', title:'Die Ährenleserinnen', artist:'Jean-François Millet', year:'1857', regions:176, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Millet malt die Feldarbeit mit ruhigen, klaren Formen und warmem Abendlicht.',
   story:'Drei Bäuerinnen beugen sich über das abgeerntete Feld und lesen die letzten Ähren auf. Hinter ihnen liegt die reiche Ernte in den Garben – ganz nah, und doch nicht für sie.',
   facts:['Das Bild wirkte damals politisch: Manche sahen darin eine Anklage, weil die Ärmsten so mühsam nach Resten suchen.',
          'Millet kannte das Landleben aus eigener Jugend in der Normandie. Er malte Arbeit nicht als Folklore, sondern ernst.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Jean-François Millet - Gleaners - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'maloja', title:'Maloja im Winter', artist:'Giovanni Giacometti', year:'um 1925', regions:184, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Giacometti setzt leuchtende Farben in lockeren, impressionistischen Flecken.',
   story:'Über dem verschneiten Dorf Maloja im Engadin steht ein heller Winterhimmel. Giovanni Giacometti, der Vater von Alberto, malte immer wieder seine Heimat, das Bergell und den Oberengadin.',
   facts:['Giovanni Giacometti starb 1933. Damit sind seine Bilder heute gemeinfrei – im Gegensatz zu denen seines berühmten Sohnes Alberto.',
          'Er war mit Ferdinand Hodler befreundet und brachte das Licht der französischen Impressionisten in die Bündner Landschaft.'],
   museum:'Privatbesitz',
   source:'Wikimedia Commons: «Giovanni Giacometti Maloja l\'inverno.jpg», gemeinfrei (Public Domain)' },
 { id:'delft', title:'Ansicht von Delft', artist:'Johannes Vermeer', year:'um 1660–1661', regions:184, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Vermeer fängt das Licht über der Stadt mit sehr feinen Übergängen ein.',
   story:'Von einem Ufer aus sehen wir Delft über den Kanal: das Wasser, die Ziegelwände, die Türme, und eine Wolkenlücke, die die Stadt aufleuchten lässt. Es ist eines der ruhigsten Stadtbilder der Kunstgeschichte.',
   facts:['Vermeer selbst stammte aus Delft und blieb der Stadt sein Leben lang treu.',
          'Das Bild zeigt die Stadt nicht als Karte, sondern als einen einzigen, stillen Augenblick nach dem Regen.'],
   museum:'Mauritshuis, Den Haag',
   source:'Wikimedia Commons: «Vermeer-view-of-delft.jpg», gemeinfrei (Public Domain)' },
 { id:'chexbres', title:'Der Genfersee von Chexbres aus', artist:'Ferdinand Hodler', year:'1905', regions:185, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Hodler ordnet See, Ufer und Himmel in ruhigen, parallelen Farbstreifen (Parallelismus).',
   story:'Von den Rebhängen über Chexbres blickt man auf den weiten Genfersee. Hodler reduziert die Landschaft auf grosse, klare Bahnen: das Türkis des Wassers, das Violett der Berge, der helle Himmel.',
   facts:['Hodler malte den See von Chexbres aus in mehreren Fassungen, bei Sonne und am Abend.',
          'Die Ruhe und die klaren Linien machen das Bild auch zum Ausmalen besonders gut lesbar.'],
   museum:'Kunstmuseum Basel',
   source:'Wikimedia Commons: «Ferdinand Hodler - Der Genfersee von Chexbres aus.jpg», gemeinfrei (Public Domain)' },
 { id:'canaletto', title:'Einfahrt in den Canal Grande', artist:'Giovanni Antonio Canal (Canaletto)', year:'um 1730', regions:185, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Canaletto zeichnet Venedig mit klarer Architektur und lebendigem Licht auf dem Wasser.',
   story:'Wir blicken vom Bacino di San Marco in den Canal Grande: links die Salute-Kirche mit ihrer weissen Kuppel, davor Gondeln und Lastboote, rechts die Paläste der Stadt.',
   facts:['Canaletto malte solche Veduten für Reisende, die sich an Venedig erinnern wollten. Viele Bilder gingen nach England.',
          'Die genaue Perspektive wirkte fast wie eine Momentaufnahme – lange vor der Fotografie.'],
   museum:'Museum of Fine Arts, Houston',
   source:'Wikimedia Commons: «Canaletto - The Entrance to the Grand Canal, Venice - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'quitasol', title:'Der Sonnenschirm', artist:'Francisco de Goya', year:'1777', regions:191, colors:14, fresh:true,
   technique:'Öl auf Leinwand, als Karton für eine Wandteppich-Manufaktur gemalt.',
   story:'Ein junger Mann hält einer sitzenden Frau den Schirm, damit die Sonne sie nicht blendet. Das Bild ist leicht, farbenfroh und voller Mode von 1777 – ein ganz anderer Goya als in seinen späteren, dunklen Werken.',
   facts:['Es entstand als Entwurf für einen Teppich im königlichen Palast El Pardo.',
          'Goya war damals noch ein junger Hofmaler. Die Heiterkeit dieser Szene zeigt, wie breit sein Werk ist.'],
   museum:'Museo del Prado, Madrid',
   source:'Wikimedia Commons: «El quitasol.jpg», gemeinfrei (Public Domain)' },
 { id:'hare', title:'Feldhase', artist:'Albrecht Dürer', year:'1502', regions:193, colors:10, fresh:true,
   technique:'Aquarell und Deckfarben auf Papier, mit feinsten Haaren und Tasthaaren.',
   story:'Der Hase sitzt ganz still, die Ohren aufmerksam, jedes einzelne Fellhaar sichtbar. Dürer hat ihn so nah und genau beobachtet, dass man das weiche Fell fast spüren kann.',
   facts:['Das Blatt ist nur etwa 25 Zentimeter hoch und trotzdem eines der berühmtesten Tierbilder der Welt.',
          'Ob Dürer einen toten oder einen lebenden Hasen vor sich hatte, ist bis heute umstritten. Die Aufmerksamkeit für das Lebendige bleibt.'],
   museum:'Albertina, Wien',
   source:'Wikimedia Commons: «Albrecht Dürer - Hare, 1502 - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'magpie', title:'Die Elster', artist:'Claude Monet', year:'1868–1869', regions:201, colors:8, fresh:true,
   technique:'Öl auf Leinwand. Monet malt Schnee nicht weiss, sondern in Blau, Rosa und gedämpftem Licht.',
   story:'Auf einem Zaun vor einem verschneiten Hof sitzt eine einzelne Elster. Die Sonne wirft lange, bläuliche Schatten, und die ganze Welt scheint stillzuhalten.',
   facts:['Monet malte das Bild im Winter in der Normandie, bei Etretat. Viele fanden den farbigen Schnee damals ungewohnt.',
          'Die Elster ist klein, aber sie gibt dem weiten Weiss einen ruhigen Mittelpunkt.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Claude Monet - The Magpie - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'eiger', title:'Eiger, Mönch und Jungfrau über dem Nebelmeer', artist:'Ferdinand Hodler', year:'1908', regions:202, colors:8, fresh:true,
   technique:'Öl auf Leinwand. Die drei Gipfel stehen als klare, rhythmische Formen über einem Nebelmeer.',
   story:'Aus einem Meer aus Wolken steigen Eiger, Mönch und Jungfrau auf. Hodler hat die berühmte Berner Oberländer Dreiergruppe so vereinfacht, dass sie fast wie ein Zeichen wirkt.',
   facts:['Das Motiv erinnert an Friedrichs «Wanderer über dem Nebelmeer», kommt aber ohne eine Figur im Vordergrund aus.',
          'Hodler malte die Jungfrau-Gruppe mehrfach, bei Sonnenaufgang, im Mondlicht und über den Wolken.'],
   museum:'Privatbesitz',
   source:'Wikimedia Commons: «Hodler - Eiger, Mönch und Jungfrau über dem Nebelmeer - 1908.jpg», gemeinfrei (Public Domain)' },
 { id:'haystacks', title:'Getreideschober am Mittag', artist:'Claude Monet', year:'1890', regions:203, colors:12, fresh:true,
   technique:'Öl auf Leinwand, aus der berühmten Serie der Getreideschober (Meules) bei Giverny.',
   story:'Zwei Heuschober stehen in der Mittagssonne auf dem Feld bei Giverny. Monet malte dasselbe Motiv zu vielen Tageszeiten, weil ihn das Licht mehr interessierte als die Schober selbst.',
   facts:['Die Serie der Meules gilt als ein Ursprung der modernen Serie in der Malerei.',
          'Im Mittagslicht werden die Schober warm und golden, der Himmel blass. Andere Fassungen zeigen Schnee, Abendrot oder Nebel.'],
   museum:'National Gallery of Australia, Canberra',
   source:'Wikimedia Commons: «Claude Monet - Meules, milieu du jour (Haystacks, midday) - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'etoile', title:'Der Stern', artist:'Edgar Degas', year:'um 1876–1877', regions:211, colors:12, fresh:true,
   technique:'Pastell auf Papier. Degas fängt Bewegung mit lockeren, leuchtenden Strichen.',
   story:'Eine Tänzerin schwebt auf der Spitze, den Kopf zurückgelegt, den Arm weit geöffnet. Um sie herum verschwimmen Bühne und Kolleginnen – der Blick ist nur für diesen einen, hellen Moment da.',
   facts:['Das Modell war vermutlich die spanische Tänzerin Rosita Mauri.',
          'Degas sass oft in der Oper, nicht nur in der Loge, sondern seitlich und hinter den Kulissen, wo die Arbeit sichtbar bleibt.'],
   museum:'Musée d’Orsay, Paris',
   source:'Wikimedia Commons: «Edgar Degas - Ballet (L\'Étoile).jpg», gemeinfrei (Public Domain)' },
 { id:'strickend', title:'Strickendes Mädchen an der Wiege', artist:'Albert Anker', year:'1885', regions:224, colors:10, fresh:true,
   technique:'Öl auf Leinwand. Anker erzählt den Alltag auf dem Land ohne Pathos, mit warmer Aufmerksamkeit.',
   story:'Ein Mädchen strickt und hütet zugleich das Kleinkind in der Wiege. Anker zeigt Verantwortung und Geborgenheit in einer einzigen, stillen Stube.',
   facts:['Solche Szenen aus dem Berner Seeland machten Anker in der Schweiz zu einem der beliebtesten Maler des 19. Jahrhunderts.',
          'Nichts ist gestellt: das Licht, das Holz, die Wäsche – alles wirkt, als könnte man eintreten.'],
   museum:'Privatbesitz',
   source:'Wikimedia Commons: «Albert Anker - Strickendes Mädchen, Kleinkind in der Wiege hütend.jpg», gemeinfrei (Public Domain)' },
 { id:'jewishbride', title:'Das jüdische Brautpaar', artist:'Rembrandt van Rijn', year:'um 1665–1669', regions:233, colors:16, fresh:true,
   technique:'Öl auf Leinwand. Rembrandt setzt kräftige, pastose Farbe, vor allem im goldenen Ärmel des Mannes.',
   story:'Ein Mann legt der Frau zärtlich die Hand an die Brust. Lange hielt man das Paar für ein jüdisches Brautpaar; heute sieht man darin oft Isaak und Rebekka aus der Bibel. Die Zärtlichkeit bleibt dieselbe.',
   facts:['Der goldene Ärmel des Mannes ist fast skulptural dick gemalt. Aus der Nähe löst er sich in reine Farbe auf.',
          'Das Bild entstand in Rembrandts letzten Lebensjahren und gilt als eines seiner stillsten Meisterwerke.'],
   museum:'Rijksmuseum, Amsterdam',
   source:'Wikimedia Commons: «Rembrandt Harmensz. van Rijn - Het Joodse bruidje.jpg», gemeinfrei (Public Domain)' },
 { id:'niesen', title:'Der Niesen', artist:'Ferdinand Hodler', year:'1910', regions:266, colors:8, fresh:true,
   technique:'Öl auf Leinwand. Der Berg wird zur klaren, fast dreieckigen Form hinter See und Regenluft.',
   story:'Der Niesen am Thunersee steigt als dunkle Pyramide auf. Hodler hat diesen Berg immer wieder gemalt, weil seine einfache, kraftvolle Silhouette zu seinem Stil passte.',
   facts:['Der Standort dieser Fassung ist «von Heustrich aus, bei Regen». Deshalb wirkt der Berg weicher und feuchter als auf sonnigen Versionen.',
          'Der Niesen ist ein Hausberg der Berner. Wer ihn einmal gesehen hat, erkennt ihn sofort.'],
   museum:'Privatbesitz',
   source:'Wikimedia Commons: «Hodler - Der Niesen - 1910.jpg», gemeinfrei (Public Domain)' },
 { id:'meninas', title:'Las Meninas', artist:'Diego Velázquez', year:'1656', regions:267, colors:18, fresh:true,
   technique:'Öl auf Leinwand. Velázquez baut einen ganzen Hofstaat in einem Raum aus Spiegeln, Blicken und Licht.',
   story:'Im Mittelpunkt steht die kleine Infantin Margarita, umgeben von Hoffräulein, Hofzwergen und einem Hund. Links malt Velázquez sich selbst – und im Spiegel hinten erscheinen König und Königin, also eigentlich wir.',
   facts:['Der Titel heisst auf Deutsch «Die Hoffräulein». Das Bild ist eines der meistbesprochenen der Welt.',
          'Velázquez war Hofmaler Philipps IV. Hier zeigt er nicht nur die königliche Familie, sondern auch sich selbst bei der Arbeit.'],
   museum:'Museo del Prado, Madrid',
   source:'Wikimedia Commons: «Las Meninas, by Diego Velázquez, from Prado in Google Earth.jpg», gemeinfrei (Public Domain)' },
 { id:'shalott', title:'The Lady of Shalott', artist:'John William Waterhouse', year:'1888', regions:307, colors:16, fresh:true,
   technique:'Öl auf Leinwand, in leuchtenden, klaren Farben der Präraffaeliten.',
   story:'Die Dame von Shalott löst sich von ihrem verfluchten Turm und gleitet den Fluss hinunter nach Camelot. Kerzen, ein Teppich und ein Kreuz liegen im Boot – sie weiss, dass dieser Weg ihr letzter ist.',
   facts:['Das Bild folgt einem Gedicht von Alfred Tennyson. Wer den Fluch bricht und aus dem Fenster auf Sir Lancelot blickt, muss sterben.',
          'Waterhouse starb 1917. Seine mittelalterlichen Szenen wirken wie eine genaue, stille Erzählung.'],
   museum:'Tate Britain, London',
   source:'Wikimedia Commons: «John William Waterhouse - The Lady of Shalott - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'harvesters', title:'Die Kornernte', artist:'Pieter Bruegel der Ältere', year:'1565', regions:318, colors:16, fresh:true,
   technique:'Öl auf Holz. Bruegel erzählt das ganze Dorfleben einer Erntelandschaft in einem einzigen Bild.',
   story:'Es ist Hochsommer: Vorn ruhen die Schnitter beim Essen, hinten wird weiter gemäht, und die Felder gehen in eine weite, goldene Landschaft über. Das Bild gehört zu Bruegels Monatsbildern, hier der Hochsommer.',
   facts:['Fünf der ursprünglich sechs Jahreszeitenbilder sind erhalten. «Jäger im Schnee» ist der Winter dazu.',
          'Bruegel zeigt Bauern nicht als Witzfiguren, sondern als Menschen bei der Arbeit, der Pause und dem Alltag.'],
   museum:'The Metropolitan Museum of Art, New York',
   source:'Wikimedia Commons: «Pieter Bruegel the Elder- The Harvesters - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'birch', title:'Buchenwald I', artist:'Gustav Klimt', year:'1902', regions:321, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Die Baumstämme stehen wie ein Teppich aus senkrechten Farbstreifen.',
   story:'Klimt geht in den Wald und lässt den Horizont fast verschwinden. Was bleibt, sind Stämme, Laub und der leuchtende Waldboden – ein Muster, das schon an seine späteren Goldbilder erinnert, aber ganz ohne Gold.',
   facts:['Um 1900 malte Klimt eine Reihe von Wald- und Gartenbildern, oft in den Sommermonaten am Attersee.',
          'Das Bild hängt in Dresden und zeigt, dass Klimt weit mehr konnte als Porträts in Gold.'],
   museum:'Galerie Neue Meister, Dresden',
   source:'Wikimedia Commons: «Gustav Klimt - Beech Grove I - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'sistine', title:'Die Sixtinische Madonna', artist:'Raffael', year:'1512–1513', regions:334, colors:16, fresh:true,
   technique:'Öl auf Leinwand. Raffael gibt den Figuren eine klare, ruhige Dreiecksordnung.',
   story:'Maria tritt mit dem Kind zwischen zwei aufgezogenen Vorhängen auf, als öffne sich eine Bühne. Zu ihren Füssen sitzen die zwei kleinen Engel, die später auf unzähligen Postkarten landeten.',
   facts:['Das Bild entstand für das Kloster San Sisto in Piacenza und kam 1754 nach Dresden.',
          'Die beiden Engel unten wurden oft einzeln abgebildet. Im ganzen Bild aber tragen sie die feierliche Erscheinung Marias mit.'],
   museum:'Gemäldegalerie Alte Meister, Dresden',
   source:'Wikimedia Commons: «Raphael - The Sistine Madonna - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'parasol', title:'Frau mit Sonnenschirm', artist:'Claude Monet', year:'1875', regions:337, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Monet malt Gegenlicht, Wind und bewegtes Gras in raschen, hellen Strichen.',
   story:'Camille, Monets Frau, steht auf einer Anhöhe, den Schirm gegen die Sonne, der kleine Jean daneben. Von unten gesehen, vor dem wehenden Himmel, wirkt sie fast schwerelos.',
   facts:['Monet hat das Motiv später noch einmal mit einer anderen Frau, seiner zweiten Frau Alice, wiederholt.',
          'Das Bild ist ein Schlüsselwerk des Impressionismus: nicht gestellt, sondern ein windiger Spaziergang, festgehalten im Licht.'],
   museum:'National Gallery of Art, Washington',
   source:'Wikimedia Commons: «Claude Monet - Woman with a Parasol - Madame Monet and Her Son - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'watering', title:'Mädchen mit Giesskanne', artist:'Pierre-Auguste Renoir', year:'1876', regions:339, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Renoir malt das Kind mit weichem Licht und leuchtenden, impressionistischen Farben.',
   story:'Ein kleines Mädchen in blauem Kleid steht im Garten, die Giesskanne in der Hand, als hätte jemand es mitten im Spiel gebeten, kurz stillzuhalten. Hinter ihm blüht der Garten schon impressionistisch auf.',
   facts:['Das Bild entstand in Paris, in der Zeit, als Renoir mit Monet und den anderen die ersten impressionistischen Ausstellungen zeigte.',
          'Trotz aller Helligkeit bleibt das Gesicht des Kindes klar und freundlich lesbar – typisch für Renoir.'],
   museum:'National Gallery of Art, Washington',
   source:'Wikimedia Commons: «Renoir - A Girl with a Watering Can.jpg», gemeinfrei (Public Domain)' },
 { id:'apples', title:'Der Äpfelkorb', artist:'Paul Cézanne', year:'um 1893', regions:343, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Cézanne baut das Stillleben aus festen Farbflächen und leicht gekippten Blickwinkeln.',
   story:'Äpfel, eine Flasche, ein Gebäck und ein geknicktes Tischtuch: Cézanne setzt alltägliche Dinge so, dass sie wie eine kleine, stabile Welt wirken. Nichts rollt weg, und doch scheint der Tisch ganz leicht zu kippen.',
   facts:['Cézanne malte Äpfel wieder und wieder. Er wollte mit ihnen die Natur auf eine stabile Grundlage stellen.',
          'Die leichte Schräge des Tisches ist Absicht. So bleibt das Auge in Bewegung, ohne dass das Bild unruhig wird.'],
   museum:'The Art Institute of Chicago',
   source:'Wikimedia Commons: «Paul Cézanne - The Basket of Apples - 1926.252 - Art Institute of Chicago.jpg», gemeinfrei (Public Domain)' },
 { id:'bluedance', title:'Blaue Tänzerinnen', artist:'Edgar Degas', year:'1898', regions:356, colors:14, fresh:true,
   technique:'Pastell auf Papier. Degas schichtet leuchtendes Blau, Türkis und warmes Orange.',
   story:'Vier Tänzerinnen rücken sich die Kostüme und das Haar zurecht, dicht zusammengedrängt, fast ohne Bühne. Degas zeigt nicht den Applaus, sondern den Moment kurz davor.',
   facts:['Das Blatt hängt im Puschkin-Museum in Moskau und gehört zu seinen späten, besonders farbstarken Pastellen.',
          'Die Körper sind angeschnitten, wie in einem Schnappschuss. Degas kannte das von der Fotografie und von japanischen Holzschnitten.'],
   museum:'Puschkin-Museum, Moskau',
   source:'Wikimedia Commons: «Edgar Degas - Blue Dancers (1898 Pushkin Museum).jpg», gemeinfrei (Public Domain)' },
 { id:'dorfschule', title:'Die Dorfschule von 1848', artist:'Albert Anker', year:'1896', regions:358, colors:14, fresh:true,
   technique:'Öl auf Leinwand. Anker füllt die ganze Stube mit Kindern, Holzbank und Schiefertafeln, ohne Unordnung.',
   story:'In einer dunklen Schulstube sitzen Kinder aller Alter, der Lehrer steht in der Mitte. Anker malte die Szene 1896, erinnerte aber an das Jahr 1848, als in der Schweiz der moderne Bundesstaat entstand – und mit ihm die Volksschule.',
   facts:['Anker selbst war lange Mitglied des Grossen Rats im Kanton Bern und kümmerte sich um Schulen und Kultur.',
          'Jedes Kind hat ein eigenes Gesicht. Wer länger schaut, findet den Träumer, den Eifrigen und den, der gerade woanders ist.'],
   museum:'Kunstmuseum Bern',
   source:'Wikimedia Commons: «Anker Die Dorfschule von 1848 1896.jpg», gemeinfrei (Public Domain)' },
 { id:'irises', title:'Schwertlilien', artist:'Vincent van Gogh', year:'1889', regions:473, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Van Gogh setzt die Blätter und Blüten in kräftigen, bewegten Farbzügen.',
   story:'Im Garten der Anstalt Saint-Rémy blühten die Schwertlilien, und Van Gogh malte sie in einem einzigen, intensiven Schub. Vorn ein fast weisser Akzent, sonst ein Meer aus Blau, Grün und warmem Rot der Erde.',
   facts:['Er malte die Iris im ersten Monat nach seiner Ankunft in Saint-Rémy, noch vor der Sternennacht.',
          'Das Bild blieb unsaniert und ohne Firnis, deshalb wirken die Farben bis heute besonders frisch.'],
   museum:'J. Paul Getty Museum, Los Angeles',
   source:'Wikimedia Commons: «Vincent van Gogh - Irises (1889).jpg», gemeinfrei (Public Domain)' },
 { id:'gotthard', title:'Die Gotthardpost', artist:'Rudolf Koller', year:'1873', regions:503, colors:18, fresh:true,
   technique:'Öl auf Leinwand. Koller verbindet genau beobachtete Tiere mit einer dramatischen Bergstrasse.',
   story:'Die Postkutsche braust die Gotthardstrasse hinunter, die Pferde fast ausser Atem, ein Hund springt zur Seite, der Hufschlag wirbelt Staub auf. Für viele ist dieses Bild das Schweizer Bild des 19. Jahrhunderts schlechthin.',
   facts:['Rudolf Koller war ein bedeutender Tiermaler. Die fünf Pferde sind einzeln porträtiert, jedes mit eigenem Charakter.',
          'Das Kunsthaus Zürich besitzt das Werk seit Langem. Es erinnert an die Zeit vor dem Gotthardtunnel, als die Passage noch eine wahre Reise war.'],
   museum:'Kunsthaus Zürich',
   source:'Wikimedia Commons: «Rudolf Koller - Die Gotthardpost (1873).jpg», gemeinfrei (Public Domain)' },
 { id:'hunters', title:'Jäger im Schnee', artist:'Pieter Bruegel der Ältere', year:'1565', regions:503, colors:18, fresh:true,
   technique:'Öl auf Holz. Bruegel erzählt eine ganze Winterlandschaft, von den Jägern vorn bis zu den winzigen Leuten auf dem Eis.',
   story:'Drei Jäger kehren mit müden Hunden ins Dorf zurück. Unten auf den zugefrorenen Teichen wird geschlittschuhgelaufen, und in der Ferne stehen scharfe, winterliche Berge. Es ist der Januar aus Bruegels Jahreszeitenfolge.',
   facts:['Trotz der Kälte ist das Bild voller Leben: ein Feuer, Vögel, Kinder auf dem Eis, ein Gasthausschild mit einem Hirsch.',
          'Zusammen mit der «Kornernte» zeigt es, wie genau Bruegel das Jahr auf dem Land kannte.'],
   museum:'Kunsthistorisches Museum, Wien',
   source:'Wikimedia Commons: «Pieter Bruegel the Elder - Hunters in the Snow (Winter) - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'kgarden', title:'Bauerngarten', artist:'Gustav Klimt', year:'um 1905–1907', regions:515, colors:12, fresh:true,
   technique:'Öl auf Leinwand. Ein dichtes Blumenmosaik aus Mohn, Glockenblumen, Margeriten und Laub.',
   story:'Klimt stand vor einem Bauerngarten und malte ihn als leuchtendes Muster, fast ohne Horizont. Die Blumen sind keine botanische Liste, sondern ein Teppich aus Farbe.',
   facts:['In denselben Sommern am Attersee entstanden auch seine ruhigeren Landschaftsbilder, etwa der Buchenwald.',
          'Das Bild war lange in Privatbesitz und zeigt den «anderen» Klimt: ohne Gold, aber ebenso dicht und festlich.'],
   museum:'Privatbesitz',
   source:'Wikimedia Commons: «Klimt bauerngarten.jpg», gemeinfrei (Public Domain)' },
 { id:'primavera', title:'Der Frühling (La Primavera)', artist:'Sandro Botticelli', year:'um 1480', regions:552, colors:18, fresh:true,
   technique:'Tempera auf Holz. Botticelli stellt die Figuren in einem Hain aus Orangenbäumen und unzähligen Blüten auf.',
   story:'In einem schattigen Hain tanzen und schreiten neun Gestalten des Frühlings: Merkur links, die drei Grazien, Venus in der Mitte, der Frühlingswind Zephyr rechts, der die Nymphe Chloris verfolgt. Über allem schwebt Amor.',
   facts:['Das Bild entstand wohl für die Familie Medici in Florenz und ist eines der berühmtesten der Frührenaissance.',
          'Botticelli hat hunderte verschiedene Blüten so genau gemalt, dass viele davon bestimmbar sind.'],
   museum:'Galleria degli Uffizi, Florenz',
   source:'Wikimedia Commons: «Sandro Botticelli - La Primavera - Google Art Project.jpg», gemeinfrei (Public Domain)' },
 { id:'terrace', title:'Zwei Schwestern auf der Terrasse', artist:'Pierre-Auguste Renoir', year:'1881', regions:618, colors:16, fresh:true,
   technique:'Öl auf Leinwand. Renoir malt die beiden Mädchen und den Garten hinter ihnen in leuchtendem, warmem Licht.',
   story:'Auf einer Terrasse über dem Wasser sitzen eine junge Frau und ein Mädchen mit einem Blumenkorb. Hinter ihnen flirrt der Garten, und die roten Hüte leuchten gegen das Grün.',
   facts:['Das Bild heisst auch «Auf der Terrasse». Es entstand in Chatou bei Paris, wo Renoir oft am Fluss malte.',
          'Trotz der vielen Einzelheiten bleibt die Szene freundlich und klar: zwei Menschen in einem Sommer, festgehalten ohne Eile.'],
   museum:'The Art Institute of Chicago',
   source:'Wikimedia Commons: «Pierre-Auguste Renoir - Two Sisters (On the Terrace) - Google Art Project.jpg», gemeinfrei (Public Domain)' }
];
